#[inline]
pub unsafe fn choices_fread(
    mut c: *mut choices_t,
    mut file: *mut FILE,
    mut input_delimiter: c_char,
) {
    let buffer_start = (*c).buffer_size;
    let mut size = buffer_start;
    let mut capacity: size_t = INITIAL_BUFFER_CAPACITY as size_t;

    while capacity <= size {
        capacity = capacity.wrapping_mul(2 as size_t);
    }

    (*c).buffer = safe_realloc((*c).buffer as *mut c_void, capacity) as *mut c_char;
    let mut buffer = (*c).buffer;

    loop {
        let read_len = fread(
            buffer.add(size) as *mut c_void,
            1 as size_t,
            capacity.wrapping_sub(size),
            file,
        );
        size = size.wrapping_add(read_len);
        if size != capacity {
            break;
        }
        capacity = capacity.wrapping_mul(2 as size_t);
        buffer = safe_realloc(buffer as *mut c_void, capacity) as *mut c_char;
        (*c).buffer = buffer;
    }

    buffer = safe_realloc(buffer as *mut c_void, size.wrapping_add(1 as size_t)) as *mut c_char;
    (*c).buffer = buffer;
    (*c).buffer_size = size.wrapping_add(1);
    *buffer.add(size) = '\0' as i32 as c_char;

    let line_end = buffer.add((*c).buffer_size);
    let mut line = buffer.add(buffer_start);
    let delim = input_delimiter as u8;

    while line < line_end {
        let remaining = line_end.offset_from(line) as usize;
        let nl = libc::memchr(line as *const c_void, delim as c_int, remaining) as *mut c_char;
        let next = if nl.is_null() {
            core::ptr::null_mut()
        } else {
            *nl = '\0' as i32 as c_char;
            nl.add(1)
        };

        if *line != 0 {
            choices_add(c, line);
        }

        if next.is_null() || next >= line_end {
            break;
        }
        line = next;
    }
}

